CREATE TABLE IF NOT EXISTS pm_users(id CHAR(36) PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,password VARCHAR(255) NOT NULL,admin BOOLEAN NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pm_sessions(token CHAR(64) PRIMARY KEY,user_id CHAR(36) NOT NULL,expires_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES pm_users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS pm_projects(id CHAR(36) PRIMARY KEY,name VARCHAR(180) NOT NULL,description TEXT,owner_id CHAR(36) NOT NULL,status VARCHAR(30) DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(owner_id) REFERENCES pm_users(id));
CREATE TABLE IF NOT EXISTS pm_members(project_id CHAR(36),user_id CHAR(36),role VARCHAR(20) NOT NULL,PRIMARY KEY(project_id,user_id),FOREIGN KEY(project_id) REFERENCES pm_projects(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES pm_users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS pm_items(id CHAR(36) PRIMARY KEY,project_id CHAR(36) NOT NULL,kind VARCHAR(25) NOT NULL,title VARCHAR(180) NOT NULL,body JSON NOT NULL,version INT NOT NULL DEFAULT 1,created_by CHAR(36) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(project_id,kind),FOREIGN KEY(project_id) REFERENCES pm_projects(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES pm_users(id));
CREATE TABLE IF NOT EXISTS pm_revisions(id CHAR(36) PRIMARY KEY,item_id CHAR(36) NOT NULL,version INT NOT NULL,title VARCHAR(180) NOT NULL,body JSON NOT NULL,actor_id CHAR(36) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(item_id,version),FOREIGN KEY(item_id) REFERENCES pm_items(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS pm_comments(id CHAR(36) PRIMARY KEY,item_id CHAR(36) NOT NULL,author VARCHAR(100) NOT NULL,user_id CHAR(36),content TEXT NOT NULL,resolved BOOLEAN DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(item_id) REFERENCES pm_items(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS pm_activity(id CHAR(36) PRIMARY KEY,project_id CHAR(36) NOT NULL,actor_id CHAR(36),action VARCHAR(300) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES pm_projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS pm_messages(id CHAR(36) PRIMARY KEY,project_id CHAR(36) NOT NULL,item_id CHAR(36),user_id CHAR(36) NOT NULL,role VARCHAR(20) NOT NULL,agent VARCHAR(100),content MEDIUMTEXT NOT NULL,status VARCHAR(20) DEFAULT 'complete',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(project_id),FOREIGN KEY(project_id) REFERENCES pm_projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS pm_models(id CHAR(36) PRIMARY KEY,name VARCHAR(100) NOT NULL,base_url VARCHAR(500) NOT NULL,model VARCHAR(180) NOT NULL,api_key TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pm_settings(name VARCHAR(100) PRIMARY KEY,value MEDIUMTEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pm_shares(token_hash CHAR(64) PRIMARY KEY,password_hash VARCHAR(100) NULL,item_id CHAR(36) NOT NULL,role VARCHAR(20) NOT NULL,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(item_id) REFERENCES pm_items(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS pm_prototype_data(id CHAR(36) PRIMARY KEY,item_id CHAR(36) NOT NULL,collection VARCHAR(80) NOT NULL,data JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(item_id) REFERENCES pm_items(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS pm_oauth(state CHAR(64) PRIMARY KEY,user_id CHAR(36) NOT NULL,expires_at DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS pm_notifications(id CHAR(36) PRIMARY KEY,event VARCHAR(30) NOT NULL,status VARCHAR(20) NOT NULL,detail VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS pm_share_sessions(session_hash CHAR(64) PRIMARY KEY,share_hash CHAR(64) NOT NULL,expires_at DATETIME NOT NULL,FOREIGN KEY(share_hash) REFERENCES pm_shares(token_hash) ON DELETE CASCADE);
